/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NOT_FOUND,
    error_codes::NOT_ACTIVE,
    error_codes::NOT_BOUND,
    error_codes::REQUEST_SHAPE_MISMATCH,
    error_codes::INVALID_BATCH,
    error_codes::SCOPE_OUTSIDE_CEILING,
    error_codes::TTL_TOO_LONG,
    error_codes::RESPONSE_TOO_LARGE,
    error_codes::RATE_LIMITED,
    error_codes::PROVIDER_SETUP_REQUIRED,
    error_codes::PROVIDER_REFUSED,
    error_codes::PROVIDER_UNAVAILABLE,
    error_codes::NOT_BROKERED,
    error_codes::NO_KEY_AGREEMENT,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `external:notFound`
    ///
    /// No account with this id exists in the named context that the caller may see. See the family conventions §2.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:notFound",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external:notActive`
    ///
    /// The account is `suspended` or `archived` and cannot be used.
    ///
    /// Declared `retryable: false`.
    pub const NOT_ACTIVE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:notActive",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external:notBound`
    ///
    /// The caller is not the consumer of any binding on this account.
    ///
    /// Declared `retryable: false`.
    pub const NOT_BOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:notBound",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external/credentials/issue:requestShapeMismatch`
    ///
    /// The request uses the shape the account's model does not take: `presign` for a model that issues sessions or tokens, which can bind neither an operation, a length nor a checksum into what it issues; or `scope` for `s3-static-presign`, which in this version issues only presigned requests. `details.expected` names the shape the model takes.
    ///
    /// Declared `retryable: false`.
    /// Declares a `detailsSchema` for the error's `details` member.
    pub const REQUEST_SHAPE_MISMATCH: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:requestShapeMismatch",
        retryable: false,
        details_schema: ::core::option::Option::Some(
            "{\"additionalProperties\":false,\"properties\":{\"expected\":{\"enum\":[\"scope\",\"presign\"],\"type\":\"string\"}},\"required\":[\"expected\"],\"type\":\"object\"}",
        ),
    };
    /// `external/credentials/issue:invalidBatch`
    ///
    /// The presign batch breaks a rule its schema cannot state: an `uploadId` missing for an operation that needs one, present beside `create-multipart`, two identical operations, or two `upload-part` operations naming the same part.
    ///
    /// Declared `retryable: false`.
    pub const INVALID_BATCH: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:invalidBatch",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external/credentials/issue:scopeOutsideCeiling`
    ///
    /// The requested scope is not inside the binding's ceiling: a prefix no ceiling prefix begins, an action the ceiling lacks, or — for `presign` — an operation whose required ceiling action the ceiling lacks.
    ///
    /// Declared `retryable: false`.
    pub const SCOPE_OUTSIDE_CEILING: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:scopeOutsideCeiling",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external/credentials/issue:ttlTooLong`
    ///
    /// `ttlSeconds` exceeds the binding's `maxTtlSeconds`. `details.maxTtlSeconds` states it.
    ///
    /// Declared `retryable: false`.
    /// Declares a `detailsSchema` for the error's `details` member.
    pub const TTL_TOO_LONG: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:ttlTooLong",
        retryable: false,
        details_schema: ::core::option::Option::Some(
            "{\"additionalProperties\":false,\"properties\":{\"maxTtlSeconds\":{\"minimum\":60,\"type\":\"integer\"}},\"required\":[\"maxTtlSeconds\"],\"type\":\"object\"}",
        ),
    };
    /// `external/credentials/issue:responseTooLarge`
    ///
    /// The presign batch is valid, but its sealed answer would exceed the bound on `sealedCredential` (262144 characters). The custodian refuses it rather than truncate the set or answer over the bound, and it does not count against the binding's rate. `details.maxOperations`, when the custodian can compute it, is how many of the batch's operations, taken in order, would fit. The caller splits the batch and asks again.
    ///
    /// Declared `retryable: false`.
    /// Declares a `detailsSchema` for the error's `details` member.
    pub const RESPONSE_TOO_LARGE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:responseTooLarge",
        retryable: false,
        details_schema: ::core::option::Option::Some(
            "{\"additionalProperties\":false,\"properties\":{\"maxOperations\":{\"maximum\":63,\"minimum\":1,\"type\":\"integer\"}},\"type\":\"object\"}",
        ),
    };
    /// `external:rateLimited`
    ///
    /// The binding's rate is exhausted. `details.retryAfterSeconds` says when to try again.
    ///
    /// Declared `retryable: true`.
    /// Declares a `detailsSchema` for the error's `details` member.
    pub const RATE_LIMITED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:rateLimited",
        retryable: true,
        details_schema: ::core::option::Option::Some(
            "{\"additionalProperties\":false,\"properties\":{\"retryAfterSeconds\":{\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"retryAfterSeconds\"],\"type\":\"object\"}",
        ),
    };
    /// `external:providerSetupRequired`
    ///
    /// The account cannot be used until its provider-side setup is redone: after a restore that could not carry its key or secret, or while a rotation awaits confirmation.
    ///
    /// Declared `retryable: false`.
    pub const PROVIDER_SETUP_REQUIRED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:providerSetupRequired",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external:providerRefused`
    ///
    /// The provider refused the custodian's request. `details.providerError` carries the provider's words, verbatim, truncated, with any credential removed.
    ///
    /// Declared `retryable: false`.
    /// Declares a `detailsSchema` for the error's `details` member.
    pub const PROVIDER_REFUSED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:providerRefused",
        retryable: false,
        details_schema: ::core::option::Option::Some(
            "{\"additionalProperties\":false,\"properties\":{\"providerError\":{\"maxLength\":2048,\"type\":\"string\"},\"providerRequestId\":{\"maxLength\":256,\"type\":\"string\"}},\"required\":[\"providerError\"],\"type\":\"object\"}",
        ),
    };
    /// `external:providerUnavailable`
    ///
    /// The provider could not be reached or did not answer in time.
    ///
    /// Declared `retryable: true`.
    pub const PROVIDER_UNAVAILABLE: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external:providerUnavailable",
        retryable: true,
        details_schema: ::core::option::Option::None,
    };
    /// `external/credentials/issue:notBrokered`
    ///
    /// The account is `sui-signer`, which issues no credentials; use external/sign.
    ///
    /// Declared `retryable: false`.
    pub const NOT_BROKERED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:notBrokered",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `external/credentials/issue:noKeyAgreement`
    ///
    /// The caller's DID offers no X25519 key-agreement key to seal the credential to: it is not a `did:key`, and its resolved DID document has no X25519 `keyAgreement` verification method.
    ///
    /// Declared `retryable: false`.
    pub const NO_KEY_AGREEMENT: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "external/credentials/issue:noKeyAgreement",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
